'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['home','行动跟进','行'],['用胶项目','业务跟进','项'],['公司','公司与人员','司'],['沟通记录','拜访记录','访'],['样品测试','样品','样'],['技术经验','经验库','验'],['每日复盘','每日复盘','复'],['export','国外开发','外'],['later','以后的助手','助'],['storage','本地数据','表'],['strategy','战略日报','报']];
const navPaths=["M3 10 12 3l9 7v10H3z M9 20v-7h6v7", "M4 4h6v16H4z M14 4h6v10h-6z", "M4 21V5h10v16 M14 10h6v11 M8 9h2 M8 13h2 M8 17h2", "M4 4h16v13H9l-5 4z M8 8h8 M8 12h5", "M8 3h8 M10 3v7L4 20h16l-6-10V3 M8 14h8", "M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1z M12 5v15", "M5 4h14v17H5z M9 3h6v3H9z M8 11h8 M8 15h5", "M3 12h18 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 3c-5 5-5 13 0 18 5-5 5-13 0-18", "M12 3v18 M3 12h18 M5 5l14 14 M5 19 19 5", "M4 4h16v16H4z M8 4v6h8V4 M8 20v-6h8v6"];
function navIcon(i){return `<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${navPaths[i]||navPaths[7]}"/></svg>`;}
const extra={联系人:['联系人','联系人'],用胶项目:['用胶项目','用胶项目'],测试轮次:['测试轮次','测试轮次']};
const labels={跟进待办:'送样、技术答复、回访和互动都在这张表',公司:'点进一家公司，先看约定、一件事和样品。',沟通记录:'客户原话和你的原话分开留',样品测试:'按公司看。一家可以有多款，每款单独显示。',技术经验:'没答上的留在待答复；问过同事要写下为什么',每日复盘:'一天只改一处'};
const friendly={'约定反馈日期':'回访 / 测试反馈日期','客户原话及时间戳':'客户说了什么','我方原话及时间戳':'我说了什么','已确认事实':'这次做成了什么','AI判断或推测':'当时判断','本次约定':'本轮只推进的一件事','待核实问题':'哪里可以改'};
const touchChannels=['微信','朋友圈','电话','面访'];
const shipped=['已寄出','已签收','测试中'];
let state=null,current=globalThis.location?.hash==='#strategy'?'strategy':'home',companyContext='',query='',statusFilter='',typeFilter='',marketFilter='',sourceFilter='',projectContext='',sampleContext='',actionWhen='today',actionWho='',editing=null,dirty=false,saving=false,visitDirty=false;
function pageOf(key){return pages.find(x=>x[0]===key)||extra[key]||[key,key];}
function rows(s){return state?.data[s]||[];}
function record(s,id){return rows(s).find(r=>r._id===id);}
function companyId(s,r){if(!r)return '';if(s==='公司')return r._id;if(r['公司编号'])return r['公司编号'];return record('用胶项目',r['项目编号'])?.['公司编号']||'';}
function companyName(s,r){return record('公司',companyId(s,r))?.['公司名称']||'未关联公司';}
function peopleOf(id){return rows('联系人').filter(x=>x['公司编号']===id);}
function openTasks(id=''){return rows('跟进待办').filter(t=>!['已完成','已取消'].includes(t['状态'])&&(!id||t['公司编号']===id));}
function localDay(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function thirdWorkday(received){if(!/^\d{4}-\d{2}-\d{2}$/.test(received||''))return '';const day=new Date(received+'T12:00:00Z'),cal=state?.workCalendar;if(!cal||!Number.isFinite(day.getTime()))return '';let n=0;while(n<3){day.setUTCDate(day.getUTCDate()+1);if(!cal.years.includes(day.getUTCFullYear()))return '';const key=day.toISOString().slice(0,10);if(cal.workdays.includes(key)||(![0,6].includes(day.getUTCDay())&&!cal.holidays.includes(key)))n++;}return day.toISOString().slice(0,10);}
function applyTestDate(container,bulk=false,force=false){const get=k=>container.querySelector(bulk?`[data-k="${k}"]`:`[data-key="${k}"]`),received=get(bulk?'received':'签收日期'),planned=get(bulk?'planned':'计划测试日期'),due=get(bulk?'due':'约定反馈日期'),basis=get(bulk?'basis':'日期依据');if(!received||!planned)return;const day=thirdWorkday(received.value),before=planned.value;if(force||!before||before===planned.dataset.auto){planned.value=day;planned.dataset.auto=day;if(due&&day&&(!due.value||due.value===due.dataset.auto)){due.value=day;due.dataset.auto=day;if(basis)basis.value='本人计划';}}const hint=container.querySelector('.test-date-hint');if(hint)hint.textContent=received.value&&!day?'该日期所需年度的中国调休日历尚未配置，请手动填写计划测试日期。':'按中国法定工作日计算，到货当天不计；可手动调整，已有日期保留。';}
function monthKey(){return localDay().slice(0,7);}
function reminder(r){if(['已完成','已取消'].includes(r['状态']))return r['状态'];if(!r['计划日期'])return '待定日期';return r['计划日期']<localDay()?'已逾期':r['计划日期']===localDay()?'今日跟进':'待跟进';}
function stageOf(r){const m=String(r['备注']||'').match(/原阶段：([^。]+)/);return m?m[1]:'';}
function badge(v){const color=/逾期|不通过|冲突|流失/.test(v)?'red':/完成|通过|已签收|成交/.test(v)?'green':/今日|等待|待确认|待定|已联系|已申请/.test(v)?'orange':'blue';return `<span class="badge ${color}">${esc(v||'未设置')}</span>`;}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200);}
async function api(url,opts){const r=await fetch(url,opts);const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data;}
async function load(){try{state=await api('/api/state');$('#saveStatus').textContent='已连接本地 Excel';$('#saveStatus').classList.remove('error');render();}catch(e){$('#saveStatus').textContent='未连接本地文件';$('#saveStatus').classList.add('error');if(!state)$('#main').innerHTML=`<div class="empty"><h2>暂时无法读取工作簿</h2><p>${esc(e.message)}</p></div>`;else toast(e.message);}}
function go(view,company=''){sourceFilter=view==='export'?'国外开发':'';if(view==='export')view='公司';if(view==='跟进待办')view='home';current=view;companyContext=company;projectContext='';sampleContext='';query='';statusFilter=view==='用胶项目'?'未结束':'';typeFilter='';marketFilter='';if(view==='home'){actionWhen='today';actionWho='';}render();window.scrollTo(0,0);}
function header(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">销售工作台</div><h1>${title}</h1><p>${sub}</p></div><div class="intro-actions">${actions}</div></div>`;}
function addButton(sheet,label){return `<button class="button primary" data-add="${sheet}">＋ ${label||'新增记录'}</button>`;}
function taskBucket(r){if(['已完成','已取消'].includes(r['状态']))return 'done';if(!r['计划日期'])return 'undated';if(r['计划日期']<localDay())return 'overdue';if(r['计划日期']===localDay())return 'today';return 'future';}
function taskOwner(r){if(r['状态']==='等待客户')return 'customer';if(r['状态']==='等待内部')return 'internal';return 'mine';}
function sameDaySample(r){if(!r['样品编号']||!r['计划日期']||['已完成','已取消'].includes(r['状态']))return false;return rows('跟进待办').filter(t=>t['样品编号']===r['样品编号']&&t['计划日期']===r['计划日期']&&!['已完成','已取消'].includes(t['状态'])).length>1;}
function samplesNeedingFollowup(){const linked=new Set(openTasks().map(t=>t['样品编号']).filter(Boolean));return rows('样品测试').filter(s=>shipped.includes(s['状态'])&&!linked.has(s._id));}
function actionTasks(){return rows('跟进待办').filter(r=>{const bucket=taskBucket(r),owner=taskOwner(r);if(actionWhen==='today'&&!((bucket==='today'||bucket==='overdue')))return false;if(actionWhen==='overdue'&&bucket!=='overdue')return false;if(actionWhen==='future'&&bucket!=='future')return false;if(actionWhen==='undated'&&bucket!=='undated')return false;if(actionWhen==='done'&&bucket!=='done')return false;if(actionWho==='mine'&&owner!=='mine')return false;if(actionWho==='customer'&&owner!=='customer')return false;if(actionWho==='internal'&&owner!=='internal')return false;if(query&&![...Object.values(r),companyName('跟进待办',r)].join(' ').toLowerCase().includes(query.toLowerCase()))return false;return true;}).sort(dueOrder);}
function taskList(tasks){return tasks.map(r=>{const person=record('联系人',r['联系人编号']);const who=person?person['姓名']+(person['职位']?`（${person['职位']}）`:''):'联系人待填';const project=r['项目编号']?(record('用胶项目',r['项目编号'])?.['终端产品']||record('用胶项目',r['项目编号'])?.['用胶部位']||r['项目编号']):'客户维护';const support=r['项目编号']?record('用胶项目',r['项目编号'])?.['需要得到的支持']:'';const when=r['计划日期']?`${r['日期依据']||'日期依据待填'}：${r['计划日期']}`:'日期待定';return `<div class="task-item"><div><button class="text-btn" data-detail="跟进待办" data-id="${esc(r._id)}">${esc(r['下一步具体动作']||r._id)}</button><p>${esc(who)} · ${esc(companyName('跟进待办',r))} · ${esc(project)}${r['样品编号']?' · '+esc(r['样品编号']):''}</p><span class="subline">${esc(when)}</span>${support?`<p>需要得到的支持：${esc(support)}</p>`:''}</div><div>${badge(reminder(r))} ${sameDaySample(r)?badge('待核'):''} ${r['状态']&&r['状态']!==reminder(r)?badge(r['状态']):''}<br><button class="text-btn" data-edit="跟进待办" data-id="${esc(r._id)}">更新</button> <button class="text-btn" data-action="delete-record" data-sheet="跟进待办" data-id="${esc(r._id)}">删除</button></div></div>`;}).join('');}
function touches(id){const keys=new Set();for(const r of rows('沟通记录'))if(r['公司编号']===id&&String(r['日期']).startsWith(monthKey())&&touchChannels.includes(r['渠道']))keys.add(r['日期']+'|'+r['渠道']);return keys.size;}
function shortList(title,hint,items,emptyText){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><small>${hint}</small></div></div>${items.length?items:`<div class="panel-content"><p class="muted">${emptyText}</p></div>`}</section>`;}
function projectTasks(id){return openTasks().filter(t=>t['项目编号']===id);}
function activeProject(p){return !['成交','流失','暂停','已结束'].includes(p['阶段']);}
function dueOrder(a,b){return (a['计划日期']||'9999').localeCompare(b['计划日期']||'9999')||a._id.localeCompare(b._id);}
function latestTalk(id){return rows('沟通记录').filter(t=>t['项目编号']===id).sort((a,b)=>String(b['日期']).localeCompare(a['日期']))[0];}
function projectGaps(p){const tasks=projectTasks(p._id),gaps=[];if(!tasks.length)gaps.push('未安排下一步');else{if(tasks.some(t=>!t['计划日期']))gaps.push('下一步日期待定');if(tasks.some(t=>!t['负责人']))gaps.push('负责人待填写');}if(p['当前卡点'])gaps.push(p['当前卡点']);return gaps;}
function projectProgress(id){const sources=[...rows('样品测试'),...rows('测试轮次')].filter(r=>r['项目编号']===id&&r['推进记录']);return sources.length?`<div class="progress-log"><small>样品 / 测试推进记录（登记时间）</small>${sources.map(r=>`<details><summary>${esc(r._id)} · ${esc(r['完整型号']||'测试轮次')}</summary><p>${esc(r['推进记录'])}</p></details>`).join('')}</div>`:'';}
function projectCards(list){return list.map(p=>{const tasks=projectTasks(p._id).sort(dueOrder),earliest=tasks.find(t=>t['计划日期'])||tasks[0],samples=rows('样品测试').filter(s=>s['项目编号']===p._id),glue=[p['用胶部位'],p['客户问题与目标']].filter(Boolean).join(' · ');return `<article class="project-card"><div class="project-head"><div><button class="text-btn" data-detail="用胶项目" data-id="${esc(p._id)}">${esc(p['终端产品']||p['用胶部位']||'待明确用胶项目')}</button><p><button class="text-btn" data-company="${esc(p['公司编号'])}">${esc(companyName('用胶项目',p))}</button></p></div>${badge(p['阶段']||'阶段待确认')}</div><div class="project-facts"><div><small>用胶点及要求</small><p>${esc(glue||'待填写')}</p></div><div><small>技术阶段</small><p>${esc(p['阶段']||'阶段待确认')}</p></div><div><small>商务进展</small><p>${esc(p['商务进度']||'待确认')}</p></div><div><small>卡点</small><p>${esc(p['当前卡点']||'尚未记录')}</p></div><div><small>下一里程碑</small><p>${esc(p['本轮推进目标']||'里程碑待填写')}</p></div>${p['需要得到的支持']?`<div><small>需要得到的支持</small><p>${esc(p['需要得到的支持'])}</p></div>`:''}</div><p class="evidence">待办 ${tasks.length} 项${earliest&&earliest['计划日期']?' · 最早回访 '+esc(earliest['计划日期']):''}</p><details class="project-more"><summary>待办、样品与档案</summary>${tasks.length?taskList(tasks):'<p class="muted">尚未安排下一步。</p>'}<div class="project-facts"><div><small>样品</small><p>${samples.length?samples.map(x=>`<button class="text-btn" data-detail="样品测试" data-id="${esc(x._id)}">${esc(x['完整型号']||x['物料名称']||x._id)} · ${esc(x['状态']||'待确认')}</button>`).join('<br>'):'未关联样品'}</p></div><div><small>现用材料</small><p>${esc(p['现用材料或型号']||'未记录')}</p></div><div><small>用量</small><p>${esc([p['客户生产用量'],p['用量单位及周期']].filter(Boolean).join(' ')||'未记录')}</p></div></div>${projectProgress(p._id)}</details><div class="project-actions"><button class="button small" data-project="${esc(p._id)}" data-add="跟进待办">安排下一步</button><button class="button small" data-project="${esc(p._id)}" data-action="visit">记沟通</button><button class="text-btn" data-edit="用胶项目" data-id="${esc(p._id)}">更新进展</button><button class="text-btn danger-text" data-action="delete-record" data-sheet="用胶项目" data-id="${esc(p._id)}">删除</button></div></article>`;}).join('');}

function homeTasks(){if(actionWhen!=='today'||actionWho)return actionTasks();return rows('跟进待办').filter(r=>{if(['已完成','已取消'].includes(r['状态']))return false;const bucket=taskBucket(r),waiting=['等待客户','等待内部'].includes(r['状态']);if(!(bucket==='today'||bucket==='overdue'||waiting))return false;if(query&&![...Object.values(r),companyName('跟进待办',r)].join(' ').toLowerCase().includes(query.toLowerCase()))return false;return true;}).sort(dueOrder);}
function todayLine(r){const late=r['计划日期']&&r['计划日期']<localDay();const when=r['计划日期']||'日期还没定';const raw=sampleNoteLine(r['下一步具体动作'])||'还没有写下要做的事';const action=raw.length>72?raw.slice(0,72)+'…':raw;const pid=r['项目编号'];const open=pid?`data-open-project="${esc(pid)}"`:`data-company="${esc(companyId('跟进待办',r))}"`;return `<div class="task-item today-line"><div><button class="text-btn" ${open}>${esc(companyName('跟进待办',r))}</button><p><button class="text-btn" ${open}>${esc(action)}</button></p><span class="subline">${esc(when)}${late?' · 已过期':''}</span></div></div>`;}
function todayLines(list){return list.map(todayLine).join('');}
function home(){
 const list=homeTasks(),need=samplesNeedingFollowup(),openMore=actionWhen!=='today'||!!actionWho;
 const titles={today:'今天要做',overdue:'已过期',future:'以后再做',undated:'还没定日期',done:'已做完'};
 const empty=actionWhen==='today'&&!actionWho?'今天没有要做的事。':'这里没有。';
 const needRows=need.map(s=>`<div class="task-item"><div><button class="text-btn" data-detail="样品测试" data-id="${esc(s._id)}">${esc(companyName('样品测试',s))} · ${esc(s['物料名称']||s['完整型号']||s._id)}</button><p>${esc(s['状态']||'待确认')}</p></div></div>`).join('');
 return `<div class="today-date">${esc(new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}))}</div>`+header(titles[actionWhen]||'今天要做','哪家公司，做什么，什么时候。',`<button class="button primary" data-action="visit">记一次沟通</button><button class="button" data-add="跟进待办">安排下一步</button>`)+
 `<div id="actionBody">${list.length?todayLines(list):`<p class="muted">${empty}</p>`}</div>`+
 `<details class="visit-more home-more" ${openMore?'open':''}><summary>其他安排</summary>${chips([['today','今天处理'],['overdue','已逾期'],['future','未来安排'],['undated','日期待定'],['done','已结束']],actionWhen,'when')}${chips([['','全部'],['mine','我来办'],['customer','等客户'],['internal','等内部']],actionWho,'who')}<div class="toolbar"><input id="search" aria-label="搜索" placeholder="找公司或这件事" value="${esc(query)}"></div>${needRows?`<p class="muted">这几款在测样品还没排跟进。</p>${needRows}`:''}</details>`;
}

const tableFields={公司:['公司名称','市场','国家或地区','行业','原阶段','人员','未完成'],跟进待办:['下一步具体动作','公司','事项类型','计划日期','提醒','状态'],联系人:['姓名','公司','职位','电话','邮箱'],用胶项目:['终端产品','公司','用胶部位','阶段'],沟通记录:['日期','公司','渠道','客户原话及时间戳','我方原话及时间戳'],样品测试:['完整型号','公司','数量','单位','对接人','快递单号','状态'],技术经验:['客户问题原话','答复人','为什么选它','证据状态'],每日复盘:['日期','关键改进与原话定位','明天一个关键目标']};
function cellValue(sheet,r,f){if(f==='公司')return companyName(sheet,r);if(f==='提醒')return reminder(r);if(f==='原阶段')return stageOf(r);if(f==='人员')return String(peopleOf(r._id).length);if(f==='未完成')return String(openTasks(r._id).length);if(f==='对接人')return record('联系人',r['收件联系人编号'])?.['姓名']||'';return r[f];}
function dataSheet(){return current==='公司'||current==='export'?'公司':current;}
function filtered(){const sheet=dataSheet();return rows(sheet).filter(r=>{if(companyContext&&companyId(sheet,r)!==companyContext)return false;if(sourceFilter==='国外开发'&&r['市场']!=='国外')return false;if(sheet==='跟进待办'&&typeFilter&&r['事项类型']!==typeFilter)return false;if(sheet==='公司'&&marketFilter==='未填地区'&&r['市场'])return false;if(sheet==='公司'&&marketFilter&&marketFilter!=='未填地区'&&r['市场']!==marketFilter)return false;if(statusFilter==='未结束'&&sheet==='用胶项目'&&!activeProject(r))return false;if(statusFilter&&statusFilter!=='未结束'&&(sheet==='跟进待办'?reminder(r):r['状态']||r['阶段']||r['证据状态'])!==statusFilter)return false;if(!query)return true;return [...Object.values(r),companyName(sheet,r),stageOf(r)].join(' ').toLowerCase().includes(query.toLowerCase());});}
function table(list){const sheet=dataSheet(),fields=tableFields[sheet];return `<div class="panel table-scroll"><table><thead><tr>${fields.map(f=>`<th>${f==='原阶段'?'阶段':esc(friendly[f]||f)}</th>`).join('')}<th></th></tr></thead><tbody>${list.map(r=>`<tr>${fields.map((f,i)=>{const v=cellValue(sheet,r,f);const shown=['状态','阶段','证据状态','提醒','原阶段','市场'].includes(f)?badge(v):i===0?`<button class="text-btn" data-detail="${sheet==='公司'?'company':sheet}" data-id="${esc(r._id)}">${esc(String(v||'查看').slice(0,80))}</button><span class="subline">${esc(r._id)}</span>`:esc(String(v??'').slice(0,100));return `<td>${shown||'—'}</td>`;}).join('')}<td><button class="text-btn" data-edit="${sheet}" data-id="${esc(r._id)}">编辑</button>${sheet==='跟进待办'?` <button class="text-btn" data-action="delete-record" data-sheet="跟进待办" data-id="${esc(r._id)}">删除</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function chips(items,active,attr){return `<div class="chips">${items.map(([v,l])=>`<button type="button" data-${attr}="${esc(v)}" class="${active===v?'active':''}">${l}</button>`).join('')}</div>`;}
function sampleStatusLine(samples){const order=['待确认','已申请','待寄出','已寄出','已签收','测试中','通过','不通过','暂停','取消'];const counts=new Map();samples.forEach(s=>{const k=s['状态']||'未设置';counts.set(k,(counts.get(k)||0)+1);});const keys=[...order.filter(k=>counts.has(k)),...[...counts.keys()].filter(k=>!order.includes(k))];return keys.length===1?`${samples.length} 款${keys[0]}`:keys.map(k=>`${k} ${counts.get(k)} 款`).join('，');}
function sampleCompanies(list){const groups=new Map();list.forEach(s=>{const id=companyId('样品测试',s)||'';if(!groups.has(id))groups.set(id,[]);groups.get(id).push(s);});return [...groups.entries()].map(([id,samples])=>{const company=record('公司',id);const name=company?.['公司名称']||'未关联公司';const title=company?`<button class="text-btn" data-detail="company" data-id="${esc(id)}">${esc(name)}</button>`:esc(name);const add=company?`<button class="text-btn" data-action="samples" data-sample-company="${esc(id)}">＋ 增加多个</button>`:'';return `<section class="panel company-samples"><div class="panel-head"><div><h2>${title}</h2><small>${esc(sampleStatusLine(samples))}</small></div>${add}</div><div class="panel-content sample-cards">${samples.map(sampleCard).join('')}</div></section>`;}).join('');}
function briefText(value,limit){const text=String(value||'').replace(/\s+/g,' ').trim();if(!text)return '';return text.length>limit?text.slice(0,limit)+'…':text;}
function experienceSummary(r){const why=briefText(r['为什么选它'],56);if(why)return why;const raw=String(r['答复原文']||'').replace(/\[段落\d+\]/g,' ').replace(/^(我自己|答复人)\s+\d{1,2}:\d{2}(?::\d{2})?\s*$/gm,' ');return briefText(raw,56)||'尚未记录答复，待补充依据。';}
function experienceCards(list){return '<div class="experience-grid">'+list.map(r=>{const question=r['客户问题原话']||'未填写问题';return `<article class="experience-card"><div class="experience-meta"><span>经验 · ${esc(r._id)}</span>${badge(r['证据状态']||'待答复')}</div><h2><button class="text-btn" data-detail="技术经验" data-id="${esc(r._id)}" title="${esc(question)}">${esc(briefText(question,42)||'未填写问题')}</button></h2><p class="experience-answer">${esc(experienceSummary(r))}</p><div class="experience-source">${esc(r['答复人']||'答复人待补充')} · ${esc(r['答复日期']||'日期待补充')}</div><div class="project-actions"><button class="text-btn" data-detail="技术经验" data-id="${esc(r._id)}">查看完整经验 →</button><button class="text-btn" data-edit="技术经验" data-id="${esc(r._id)}">编辑</button></div></article>`;}).join('')+'</div>';}
function sampleStatusLabel(v){return v==='已签收'?'已收样':(v||'待确认');}
function businessBoard(list){const ids=new Set(list.map(p=>p._id));const items=(state.businessRows||[]).filter(r=>ids.has(r.id));if(!state.businessRows)return '<p class="muted">业务表还没有读到，请刷新。</p>';if(!items.length)return '<p class="muted">还没有用胶项目。</p>';const statuses=state.schema['样品测试'].find(f=>f.name==='状态')?.options||[];return items.map(item=>{const project=item.project||{};const samples=item.samples||[];const blocks=samples.map(s=>{const name=s['完整型号']||s['物料名称']||s._id;const rounds=trialRounds(s._id).map(r=>[r['日期'],r['状态'],r['测试结果与原因']].filter(Boolean).join(' · ')).join('\n');const task=(item.tasks||[]).find(t=>t['样品编号']===s._id);const step=sampleNoteLine(task?.['下一步具体动作']||'');return `<div class="biz-sample" data-sample-id="${esc(s._id)}"><div class="biz-sample-head"><strong>${esc(name)}</strong><span>${esc(sampleStatusLabel(s['状态']))}${step?' · '+esc(step):''}</span></div><label>状态<select data-sample-field="状态">${statuses.map(v=>`<option value="${esc(v)}" ${s['状态']===v?'selected':''}>${esc(sampleStatusLabel(v))}</option>`).join('')}</select></label><label>寄出日期<input data-sample-field="寄出日期" type="date" value="${esc(s['寄出日期']||'')}"></label><label>收样日期<input data-sample-field="签收日期" type="date" value="${esc(s['签收日期']||'')}"></label><label>计划测试<input data-sample-field="计划测试日期" type="date" value="${esc(s['计划测试日期']||'')}"></label><label>反馈日期<input data-sample-field="约定反馈日期" type="date" value="${esc(s['约定反馈日期']||'')}"></label><label>日期依据<select data-sample-field="日期依据"><option value="">待确认</option><option ${s['日期依据']==='本人计划'?'selected':''}>本人计划</option><option ${s['日期依据']==='客户约定'?'selected':''}>客户约定</option></select></label><label>改期原因<input data-sample-field="延期原因" placeholder="改了反馈日期再填"></label><label class="wide">测试结果<textarea data-sample-field="测试结果与证据">${esc(s['测试结果与证据']||'')}</textarea></label><details><summary>这款的历史</summary><p>${esc([s['推进记录'],rounds].filter(Boolean).join('\n')||'还没有历史。')}</p></details></div>`;}).join('')||'<p class="muted">还没有样品。</p>';const supplement=['当前工艺与固化条件','现用材料或型号','竞品主要问题','包装规格','客户生产用量','用量单位及周期','当前售价','可接受价格预估','项目外部现状','方案性质','项目备注'];const extra=supplement.map(name=>`<label class="${/备注|现状|问题|工艺/.test(name)?'wide':''}">${esc(name)}<input data-project-field="${esc(name)}" value="${esc(project[name]??'')}"></label>`).join('');const basis=item.tasks?.[0]?.['日期依据'];return `<article class="biz-row" data-project-row="${esc(item.id)}" id="project-${esc(item.id)}"><button type="button" class="biz-line" data-open-project="${esc(item.id)}"><span><small>客户</small>${esc(item.company||'未关联公司')}</span><span><small>用胶点及要求</small>${esc(item.requirements||project['终端产品']||'待补充')}</span><span><small>联系人</small>${esc(item.person||'待指定')}</span><span><small>推荐型号</small>${esc((item.models||[]).join('、')||'待定')}</span><span><small>样品进度</small>${esc(item.sampleSummary)}</span><span><small>最新反馈</small>${esc(sampleNoteLine(item.feedback)||'还没有反馈')}</span><span><small>下一步</small>${esc(sampleNoteLine(item.nextAction)||'还没有下一步')}</span><span><small>跟进日期</small>${esc(item.nextDate||'日期还没定')}</span><span><small>所需支持</small>${esc(item.support||'没有')}</span></button><details class="visit-more biz-fold" ${projectContext===item.id?'open':''}><summary>更新这一行</summary><p class="muted">${esc([item.company,project['终端产品'],item.person,(item.models||[]).join('、')].filter(Boolean).join(' · '))}</p><div class="form-grid"><label class="wide">最新反馈<textarea data-project-field="最新反馈">${esc(project['最新反馈']||'')}</textarea></label><label>反馈日期<input data-project-field="反馈日期" type="date" value="${esc(project['反馈日期']||'')}"></label><label class="wide">所需支持<input data-project-field="需要得到的支持" value="${esc(project['需要得到的支持']||'')}"></label><label class="wide">下一步<input data-follow="action" value="${esc(item.nextAction||'')}"></label><label>跟进日期<input data-follow="date" type="date" value="${esc(item.nextDate||'')}"></label><label>日期依据<select data-follow="basis"><option ${basis!=='客户约定'?'selected':''}>本人计划</option><option ${basis==='客户约定'?'selected':''}>客户约定</option></select></label><label>改期原因<input data-follow="reason" placeholder="改了日期再填"></label><input type="hidden" data-follow="task" value="${esc(item.primaryTaskId||'')}"></div><h3>样品</h3><div class="biz-samples">${blocks}</div><details class="visit-more"><summary>补充业务资料</summary><div class="form-grid">${extra}</div></details><p class="biz-error" data-error></p><button type="button" class="button primary" data-save-project="${esc(item.id)}">保存这一行</button></details></article>`;}).join('');}
async function saveBusiness(id){const root=document.querySelector(`[data-project-row="${id}"]`);if(!root)return;const err=root.querySelector('[data-error]');const project={};root.querySelectorAll('[data-project-field]').forEach(el=>{project[el.dataset.projectField]=el.value;});const samples=[...root.querySelectorAll('[data-sample-id]')].map(box=>{const item={id:box.dataset.sampleId};box.querySelectorAll('[data-sample-field]').forEach(el=>{if(el.dataset.sampleField==='延期原因'&&!el.value.trim())return;item[el.dataset.sampleField]=el.value;});return item;});const follow={taskId:root.querySelector('[data-follow="task"]').value,下一步具体动作:root.querySelector('[data-follow="action"]').value,计划日期:root.querySelector('[data-follow="date"]').value,日期依据:root.querySelector('[data-follow="basis"]').value,延期原因:root.querySelector('[data-follow="reason"]').value};err.textContent='';try{const res=await api('/api/project-update',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Token':$('meta[name="workspace-token"]').content},body:JSON.stringify({version:state.version,id,project,samples,follow})});state.version=res.version;projectContext=id;await load();toast('已保存这一行。');}catch(e){if(err)err.textContent=e.message;}}
function paintList(list){const sheet=dataSheet();const body=!list.length?`<div class="empty empty-panel"><span class="empty-symbol">${sheet==='技术经验'?'学':'◇'}</span><h2>${query||statusFilter?'没有匹配的记录':sheet==='技术经验'?'把经验积累在这里':'这里还没有记录'}</h2><p>${sheet==='技术经验'?'记录问题、答复依据和适用条件，方便下次遇到同类问题时查找。':'试试调整筛选条件，或从右上角新增一条记录。'}</p></div>`:sheet==='技术经验'?experienceCards(list):sheet==='沟通记录'?talkCards(list):sheet==='样品测试'?sampleCompanies(list):sheet==='用胶项目'?businessBoard(list):table(list);const count=sheet==='样品测试'?`${new Set(list.map(s=>companyId('样品测试',s)||'')).size} 家 · ${list.length} 条`:`${list.length} 条 / 容量 ${state.capacity} 条`;return {body,count};}
function listing(){const sheet=dataSheet(),list=filtered();const statuses=sheet==='用胶项目'?['未结束',...(state.schema[sheet]?.find(f=>f.name==='阶段')?.options||[])]:sheet==='跟进待办'?['今日跟进','已逾期','待跟进','待定日期','已完成','已取消']:state.schema[sheet]?.find(f=>['状态','阶段','证据状态'].includes(f.name))?.options||[];const title=sourceFilter==='国外开发'?'国外开发':pageOf(sheet)[1];const sub=sourceFilter==='国外开发'?'按市场为国外筛选；邮箱、展会、转介绍等渠道统一保留。':(sheet==='用胶项目'?'一行一个用胶项目。点开后改反馈、下一步和每款样品。':labels[sheet]||'');const action=sheet==='沟通记录'?'<button class="button primary" data-action="visit">记一次拜访</button>':sheet==='样品测试'?'<button class="button primary" data-action="samples">＋ 增加多个样品</button>':addButton(sheet,sheet==='公司'?'新增客户':'新增记录');return header(title,sub,action)+(companyContext?`<div class="context"><span>当前公司：${esc(record('公司',companyContext)?.['公司名称']||companyContext)}</span><button data-action="clear-context">查看全部 ×</button></div>`:'')+(sheet==='跟进待办'?chips([['','全部'],['送样','送样'],['技术答疑','技术答疑'],['定期回访','定期回访'],['拜访','拜访'],['邮件跟进','邮件'],['社媒跟进','社媒']],typeFilter,'type'):'')+(sheet==='公司'&&!sourceFilter?chips([['','全部'],['国内','国内'],['国外','国外'],['未填地区','地区未填']],marketFilter,'market'):'')+`<div class="toolbar"><input id="search" aria-label="搜索" placeholder="搜索公司、人、阶段或记录" value="${esc(query)}">${statuses.length?`<select id="statusFilter" aria-label="状态"><option value="">全部状态</option>${statuses.map(s=>`<option ${statusFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select>`:''}<span class="count">${paintList(list).count}</span></div><div id="listBody">${paintList(list).body}</div>`;}
function talkGroups(list){const map=new Map();for(const t of [...list].sort((a,b)=>String(a['日期']).localeCompare(String(b['日期']))||String(a._id).localeCompare(String(b._id)))){const key=t['公司编号']||t._id;if(!map.has(key))map.set(key,[]);map.get(key).push(t);}return [...map.values()].sort((a,b)=>String(b[b.length-1]['日期']).localeCompare(String(a[a.length-1]['日期']))||String(b[b.length-1]._id).localeCompare(String(a[a.length-1]._id)));}
function talkSpan(group){const dates=[...new Set(group.map(t=>String(t['日期']||'').slice(0,10)).filter(Boolean))];if(!dates.length)return group[0]._id;return dates.length===1?dates[0]:`${dates[0]} – ${dates[dates.length-1]}`;}
function talkCards(list){return talkGroups(list).map(group=>{const t=group[group.length-1];return `<section class="panel"><div class="panel-head"><div><h2><button class="text-btn" data-detail="沟通记录" data-id="${esc(t._id)}">${esc(talkSpan(group))} · ${esc(companyName('沟通记录',t))}</button></h2><small>${esc(group.map(x=>x._id).join(' · '))} · 同一客户接成一条</small></div><div>${group.map(x=>`<button class="text-btn" data-edit="沟通记录" data-id="${esc(x._id)}">编辑 ${esc(x._id)}</button>${x['客户原话及时间戳']?.includes('[段落')?` <button class="text-btn" data-upload="${esc(x._id)}">上传校对稿</button>`:''}`).join(' ')}</div></div><div class="panel-content">${threadFrame(group)}</div></section>`;}).join('');}
function personButton(p){return `<button class="person" data-detail="联系人" data-id="${esc(p._id)}"><span><b>${esc(p['姓名'])}</b><small>${esc([p['职位'],p['电话'],p['邮箱']].filter(Boolean).join(' · ')||'联系方式待补充')}</small></span></button>`;}
function canonSpeaker(name){return String(name||'').replace(/\s+/g,'');}
function parseSide(text,side){const out=[];let current=null;for(const raw of String(text||'').split('\n')){const line=raw.trim();if(!line||line.startsWith('以下是现场主谈'))continue;const m=line.match(/^(\d{1,2}:\d{2})\s+([^：:]{1,30}?)(?:\s+\[段落(\d+)\])?[：:](.*)$/);if(m){current={t:m[1],name:canonSpeaker(m[2]),order:m[3]?Number(m[3]):0,text:m[4].trim(),side};out.push(current);}else if(current){current.text+=(current.text?'\n':'')+line;}else{current={t:'',name:side==='ours'?'我':'客户',order:0,text:line,side};out.push(current);}}return out.filter(u=>u.text);}
function timeNum(t){const m=String(t||'').match(/^(\d{1,2}):(\d{2})$/);return m?(+m[1])*60+(+m[2]):100000;}
function utterances(talk,raw=false){const all=[...parseSide((!raw&&talk['客户整理稿及时间戳'])||talk['客户原话及时间戳'],'customer').map((u,i)=>({...u,i})),...parseSide((!raw&&talk['我方整理稿及时间戳'])||talk['我方原话及时间戳'],'ours').map((u,i)=>({...u,i:i+10000}))];all.sort((a,b)=>timeNum(a.t)-timeNum(b.t)||(a.order&&b.order?a.order-b.order:0)||(a.side===b.side?a.i-b.i:a.side==='customer'?-1:1));return all;}
const wine={bg:'#7f1d2e',fg:'#fff'};
const buyColor={bg:'#fef3c7',fg:'#92400e'};
const techColors=[{bg:'#dbeafe',fg:'#1e3a8a'},{bg:'#cffafe',fg:'#155e75'},{bg:'#dcfce7',fg:'#14532d'},{bg:'#e0f2fe',fg:'#0c4a6e'},{bg:'#fce7f3',fg:'#9d174d'},{bg:'#ecfccb',fg:'#3f6212'}];
const otherCustomerColors=[{bg:'#fce7f3',fg:'#9d174d'},{bg:'#ecfccb',fg:'#3f6212'},{bg:'#e0f2fe',fg:'#0c4a6e'}];
const customerColors=techColors;
const ourColors=[{bg:'#1e3a5f',fg:'#fff'},{bg:'#134e4a',fg:'#fff'},{bg:'#312e81',fg:'#fff'},{bg:'#334155',fg:'#fff'},{bg:'#3f6212',fg:'#fff'}];
const fixedColors={我:wine,我自己:wine,同事甲:{bg:'#c2410c',fg:'#fff'},答复人:{bg:'#e9d5ff',fg:'#4c1d95'},我方领导:{bg:'#312e81',fg:'#fff'}};
function matchPerson(name,companyId){const people=peopleOf(companyId);const exact=people.find(p=>canonSpeaker(p['姓名'])===name);if(exact)return exact;const surname=String(name||'').replace(/(经理|总|工|小姐|先生|老师)$/,'');if(!surname||surname===name)return null;const hits=people.filter(p=>canonSpeaker(p['姓名']).startsWith(surname));return hits.length===1?hits[0]:null;}
function speakerRole(name,companyId){if(/技术/.test(name))return 'tech';if(/采购/.test(name))return 'buy';const person=matchPerson(name,companyId);const title=[person?.['职位'],person?.['项目职责']].filter(Boolean).join(' ');if(/技术|工程师/.test(title))return 'tech';if(/采购/.test(title))return 'buy';return '';}
function takeColor(list,used,prefer){const order=prefer==null?[...list.keys()]:[prefer,...list.keys()].filter((v,i,a)=>a.indexOf(v)===i);for(const i of order)if(!used.has(i)){used.add(i);return list[i];}return list[used.size%list.length];}
function speakerColors(companyId){const talks=rows('沟通记录').filter(t=>t['公司编号']===companyId).sort((a,b)=>String(a['日期']).localeCompare(String(b['日期']))||String(a._id).localeCompare(String(b._id)));const assigned={},usedOther=new Set(),usedOurs=new Set();let techN=0;for(const talk of talks)for(const u of utterances(talk)){if(assigned[u.name])continue;if(fixedColors[u.name]){assigned[u.name]=fixedColors[u.name];continue;}if(u.side==='ours'){assigned[u.name]=takeColor(ourColors,usedOurs,null);continue;}const role=speakerRole(u.name,companyId);if(role==='buy'){assigned[u.name]=buyColor;continue;}if(role==='tech'){assigned[u.name]=techColors[Math.min(techN,techColors.length-1)];techN++;continue;}assigned[u.name]=takeColor(otherCustomerColors,usedOther,null);}return assigned;}
function companyTalks(id){return rows('沟通记录').filter(t=>t['公司编号']===id).sort((a,b)=>String(a['日期']).localeCompare(String(b['日期']))||String(a._id).localeCompare(String(b._id)));}
function orderStamp(t){const m=String(t||'').match(/^(\d{1,2}):(\d{2})$/);return !!(m&&+m[1]===0&&+m[2]<10);}
function shownClock(t,date,orderOnly){if(orderOnly||!t)return String(date||'').slice(0,10);return t;}
function chatTool(talk){const channel=talk['渠道']||'';const person=record('联系人',talk['联系人编号']);const blob=[talk['已确认事实'],talk['客户原话及时间戳'],talk['我方原话及时间戳'],person?.['微信或社媒'],channel].filter(Boolean).join('\n');if(channel==='邮件'){const email=String(person?.['邮箱']||'').trim();const subject=(blob.match(/Subject:\s*([^.\n]+)/)||[])[1];const q=[email,subject?`subject:"${subject.trim()}"`:''].filter(Boolean).join(' ');return {name:'邮件',href:q?`https://mail.google.com/mail/u/0/#search/${encodeURIComponent(q)}`:''};}if(/whatsapp/i.test(blob))return {name:'WhatsApp',href:''};if(channel==='微信'||/微信/.test(blob))return {name:'微信',href:''};return {name:channel||'渠道待填',href:''};}
function threadFrame(talks){const list=(Array.isArray(talks)?talks:[talks]).filter(Boolean);if(!list.length)return '<p class="muted">还没有拜访记录。</p>';const sorted=[...list].sort((a,b)=>String(a['日期']).localeCompare(String(b['日期']))||String(a._id).localeCompare(String(b._id)));const colors=speakerColors(sorted[0]['公司编号']);const body=sorted.map(talk=>{const original=utterances(talk,true);const has=!!(talk['客户整理稿及时间戳']||talk['我方整理稿及时间戳']);const fluent=has?utterances(talk,false):[];const date=String(talk['日期']||'').slice(0,10);const orderOnly=original.length>0&&original.every(u=>orderStamp(u.t));const tool=chatTool(talk);const toolKey=tool.name==='WhatsApp'?'whatsapp':tool.name==='邮件'?'mail':tool.name==='微信'?'wechat':tool.name==='面访'?'visit':tool.name==='电话'?'phone':'other';const head=`<div class="seg"><strong class="chat-tool chat-tool-${toolKey}">${esc(tool.name)}</strong><span class="seg-meta">${esc([date||'日期待填',talk._id].filter(Boolean).join(' · '))}</span>${tool.href?`<a class="mail-link" href="${esc(tool.href)}" target="_blank" rel="noopener noreferrer">在邮箱查看原对话</a>`:''}</div>${has?'':'<p class="seg-miss">这段还没有中文。</p>'}`;const bubbles=original.length?original.map((u,i)=>{const color=colors[u.name]||(u.side==='ours'?fixedColors['我']:customerColors[0]);const zh=has&&fluent[i]?fluent[i].text:'';const stamp=shownClock(u.t,date,orderOnly);return `<div class="bubble ${u.side==='ours'?'right':'left'}" style="background:${color.bg};color:${color.fg}"><span class="who">${esc(u.name)}${stamp?' · '+esc(stamp):''}</span><p data-original="${esc(u.text)}" data-fluent="${esc(zh)}">${esc(u.text)}</p></div>`;}).join(''):'<p class="muted">还没有拆成对话的原话。</p>';return `<article class="turn-box">${head}${bubbles}</article>`;}).join('');return `<div class="thread-frame"><div class="thread-tools"><button type="button" class="button small" data-action="toggle-zh">语句通顺的中文</button></div><div class="thread">${body}</div></div>`;}
function showLatestTalks(root=document){(root||document).querySelectorAll('.thread').forEach(thread=>{const box=thread.querySelector('.turn-box:last-child');if(!box)return;const top=box.getBoundingClientRect().top-thread.getBoundingClientRect().top+thread.scrollTop;thread.scrollTop=Math.max(0,top);});}
function trialRounds(id){return rows('测试轮次').filter(r=>r['样品编号']===id).sort((a,b)=>a._id.localeCompare(b._id));}
function trialHistory(id){const list=trialRounds(id);return `<div class="trial-head"><h2>测试轮次 · ${list.length} 条</h2><button class="button small primary" data-trial="${esc(id)}">＋ 新增一轮测试</button></div><p class="muted">复测请新增一轮；原样品记录与历史结果保留。轮次结论不会自动改写样品或项目状态。</p>${list.length?list.map((r,i)=>`<article class="trial-row"><div class="experience-meta"><strong>第 ${i+1} 轮 · ${esc(r['日期'])}</strong>${badge(r['状态'])}</div><p>测试人：${esc(record('联系人',r['测试负责人编号'])?.['姓名']||'待明确')}</p><p>条件：${esc(r['测试条件']||'待明确')}</p><p>合格标准：${esc(r['合格标准']||'待明确')}</p><p>结果与原因：${esc(r['测试结果与原因']||'尚无结论')}</p><p>证据：${esc(r['证据路径或链接']||'待补充')}</p>${r['任务编号']?`<button class="text-btn" data-detail="跟进待办" data-id="${esc(r['任务编号'])}">查看关联跟进</button>`:''}<p>下一步：${esc(r['下一步具体动作']||'待安排')} · ${esc(r['约定反馈日期']||'反馈日期待定')}</p><button class="text-btn" data-edit="测试轮次" data-id="${esc(r._id)}">补充本轮记录</button></article>`).join(''):'<p class="muted">尚未登记独立轮次。已有样品反馈仍保留在下方原记录中。</p>'}`;}
function sampleNoteLine(text){const piece=String(text||'').trim().split(/[。！？\n]/).map(s=>s.trim()).find(Boolean);return piece||'';}
function sampleFacts(s){const bits=[];if(s['数量']!==''&&s['数量']!=null)bits.push(s['单位']?`${s['数量']} ${s['单位']}`:String(s['数量']));const person=record('联系人',s['收件联系人编号'])?.['姓名'];if(person)bits.push(person);if(s['快递单号'])bits.push(s['快递单号']);return bits.join(' · ');}
function sampleCard(s){const facts=sampleFacts(s),note=sampleNoteLine(s['备注']);return `<article class="card sample-card"><button class="text-btn" data-detail="样品测试" data-id="${esc(s._id)}">${esc(s['物料名称']||s['完整型号']||'物料待填写')}</button>${s['物料名称']&&s['完整型号']?`<p>对内型号：${esc(s['完整型号'])}</p>`:''}${facts?`<p>${esc(facts)}</p>`:''}${note?`<p class="sample-note">${esc(note)}</p>`:''}${badge(s['状态'])}<div class="sample-delete"><button type="button" class="text-btn" data-action="delete-record" data-sheet="样品测试" data-id="${esc(s._id)}">删除</button></div></article>`;}
function sampleBoard(samples){const head=`<div class="panel-head"><div><h2>样品</h2>${samples.length?`<small>${samples.length} 款</small>`:''}</div><button class="text-btn" data-action="samples">＋ 增加多个</button></div>`;if(!samples.length)return `<section class="panel">${head}<div class="panel-content"><p class="muted">还没有样品记录。没申请之前，可以只在跟进里写送样。</p></div></section>`;return `<section class="panel">${head}<div class="panel-content sample-cards">${samples.map(sampleCard).join('')}</div></section>`;}
function progressText(company,samples,tasks){const parts=[];if(!samples.length)parts.push('还没有样品记录');else{const order=['待确认','已申请','待寄出','已寄出','已签收','测试中','通过','不通过','暂停','取消'];const counts=new Map();samples.forEach(s=>{const k=s['状态']||'未设置';counts.set(k,(counts.get(k)||0)+1);});const keys=[...order.filter(k=>counts.has(k)),...[...counts.keys()].filter(k=>!order.includes(k))];const summary=keys.length===1?`${samples.length} 款${keys[0]}`:keys.map(k=>`${k} ${counts.get(k)} 款`).join('，');const unsent=samples.every(s=>['待确认','已申请','待寄出'].includes(s['状态']||'')&&!s['寄出日期']);parts.push(unsent?`${summary}，尚未寄出`:summary);const dates=samples.map(s=>s['约定反馈日期']).filter(Boolean).sort();if(dates.length)parts.push('约定反馈 '+dates[0]);const names=[...new Set(samples.map(s=>record('联系人',s['收件联系人编号'])?.['姓名']).filter(Boolean))];if(names.length)parts.push('对接人：'+names.join('、'));const blank=samples.filter(s=>(s['数量']===''||s['数量']==null)||!s['快递单号']).length;if(blank)parts.push(`数量或快递单号未填 ${blank} 款`);}const stage=stageOf(company);if(stage)parts.push('原阶段：'+stage);parts.push('未完成跟进 '+tasks.length);return parts.join('。')+'。';}
function companyPage(id){const r=record('公司',id);if(!r){go('公司');return;}current='companyDetail';companyContext=id;projectContext='';const people=peopleOf(id),tasks=openTasks(id),talks=companyTalks(id),projects=rows('用胶项目').filter(x=>x['公司编号']===id),samples=rows('样品测试').filter(x=>companyId('样品测试',x)===id);const recent=rows('沟通记录').filter(t=>t['公司编号']===id).sort((a,b)=>String(b['日期']).localeCompare(a['日期']))[0];const next=[...tasks].sort(dueOrder)[0];const agreed=sampleNoteLine(recent?.['本次约定']);const samplePoints=samples.map(s=>{const person=record('联系人',s['收件联系人编号'])?.['姓名'];const bits=[s['状态'],person,s['快递单号']].filter(Boolean);return `<p><button class="text-btn" data-detail="样品测试" data-id="${esc(s._id)}">${esc(s['物料名称']||s['完整型号']||'物料待填写')}</button> ${esc(bits.join(' · '))}</p>`;}).join('')||'<p class="muted">还没有样品。</p>';$('#crumb').textContent=r['公司名称'];$('#main').innerHTML=header(esc(r['公司名称']),esc([stageOf(r),r['市场'],r['国家或地区'],r['行业']].filter(Boolean).join(' · ')),`<button class="button primary" data-action="visit">记一次拜访</button>`)+`<button class="text-btn" data-view="公司">← 全部公司</button><section class="panel company-now"><div class="panel-content"><div class="fact-label">上次约定</div><p>${esc(agreed||'还没有记下约定。')} ${recent?`<button class="text-btn" data-detail="沟通记录" data-id="${esc(recent._id)}">${esc(recent['日期'])}</button>`:''}</p><div class="fact-label">还没做完</div>${next?`<p><button class="text-btn" data-detail="跟进待办" data-id="${esc(next._id)}">${esc(next['下一步具体动作']||'还没有写下要做的事')}</button></p><p class="muted">${esc(next['计划日期']||'日期还没定')}</p>`:'<p>没有还没做完的事。</p>'}<div class="fact-label">样品</div>${samplePoints}<button class="text-btn" data-action="samples">＋ 增加样品</button></div></section><details class="visit-more company-more"><summary>需要时再看</summary><p class="muted">本月互动 ${touches(id)}/4${r['市场']==='国内'&&stageOf(r)!=='流失'?'，国内在跟客户按这个数看':'，这条月度要求不套到流失或国外客户'}。</p><p><strong>待答问题：</strong>${esc(sampleNoteLine(recent?.['待核实问题'])||'没有记下。')} ${recent?`<button class="text-btn" data-detail="沟通记录" data-id="${esc(recent._id)}">核对原记录</button>`:''}</p><p><strong>项目对接人：</strong>${esc([...new Set(projects.filter(activeProject).map(p=>record('联系人',p['主要联系人编号'])?.['姓名']).filter(Boolean))].join('、')||'还没有指定。')}</p><section class="panel"><div class="panel-head"><h2>沟通</h2>${talks.length?`<small>${esc(talkSpan(talks))} · ${talks.length} 次</small>`:''}</div><div class="panel-content">${talks.length?threadFrame(talks):'<p class="muted">还没有拜访记录。</p>'}</div></section><div class="split"><section class="panel"><div class="panel-head"><div><h2>人员</h2><small>${people.length} 人</small></div><button class="text-btn" data-add="联系人">＋ 添加</button></div><div class="panel-content">${people.length?people.map(personButton).join(''):'<p class="muted">没有联系人。没有姓名不要编。</p>'}</div></section><section class="panel"><div class="panel-head"><div><h2>跟进</h2></div><button class="text-btn" data-add="跟进待办">＋ 安排</button></div>${tasks.length?taskList(tasks):'<div class="panel-content"><p class="muted">没有未完成事项。</p></div>'}</section></div><section class="panel"><div class="panel-head"><h2>用胶点</h2><button class="text-btn" data-add="用胶项目">＋ 添加</button></div>${projects.length?projects.map(p=>`<div class="task-item"><div><button class="text-btn" data-detail="用胶项目" data-id="${esc(p._id)}">${esc(p['终端产品']||p['用胶部位']||p._id)}</button><p>${esc([p['用胶部位'],p['现用材料或型号']].filter(Boolean).join(' · '))}</p></div>${badge(p['阶段'])}</div>`).join(''):'<div class="panel-content"><p class="muted">还没有用胶点。</p></div>'}</section>${sampleBoard(samples)}<section class="panel"><div class="panel-head"><h2>公司资料</h2><span class="badge">${esc(id)}</span></div><div class="panel-content"><div class="progress-now"><div class="fact-label">目前进度</div><p class="fact-value">${esc(progressText(r,samples,tasks))}</p></div><div class="fact-grid">${Object.entries(r).filter(([k])=>!k.startsWith('_')&&!String(k).includes('〔自动〕')).map(([k,v])=>`<div class="${/备注|来源/.test(k)?'wide':''}"><div class="fact-label">${esc(k)}</div><div class="fact-value">${esc(v)||'待补充'}</div></div>`).join('')}</div><button class="button" data-edit="公司" data-id="${esc(id)}">编辑公司</button></div></section></details>`;showLatestTalks($('#main'));}
function later(){return header('以后的助手','这三个位置先空着，不接模型，也不生成客户。')+`<div class="cards">${[['拜访复盘','把一次拜访收成一处可改的动作'],['样品缺口','看出哪家还没申请、哪家寄出没反馈'],['经验提问','把没答上的型号问题交给熟练销售']].map(([t,d])=>`<article class="card"><h2>${t}</h2><p>${d}</p><p>现在仍用拜访记录、样品和经验库手工填写。</p></article>`).join('')}</div>`;}
function storage(){return header('本地数据','网页读写下面这一个 Excel。不回写 Notion。')+`<section class="panel"><div class="panel-content"><div class="path">${esc(state.path)}</div><p class="muted">最后修改：${esc(new Date(state.modified).toLocaleString('zh-CN'))} · 备份 ${state.backupCount} 份</p><a class="button primary" href="/download" download="客户数据.xlsx">下载当前 Excel 副本</a><p class="notice">每张表容量 ${state.capacity} 条。录音先转成文字再贴。恢复备份时先关工作台，替换数据文件后再打开。</p></div></section>`;}
function render(){strategyObserver?.disconnect();if(!state)return;const exportOn=sourceFilter==='国外开发'&&current==='公司';$('#nav').innerHTML=pages.map(([key,l,icon],i)=>{const on=key==='export'?exportOn:key==='公司'?current==='公司'&&!exportOn||current==='companyDetail':current===key;return `${i===0?'<div class="nav-group">工作空间</div>':i===5?'<div class="nav-group">学习与积累</div>':i===7?'<div class="nav-group">更多工具</div>':''}<a href="#${key}" data-view="${key}" ${on?'aria-current="page"':''} class="${on?'active':''}"><span class="nav-icon">${navIcon(i)}</span>${l}${on?'<span class="nav-indicator"></span>':''}</a>`;}).join('');$('#crumb').textContent=current==='companyDetail'?(record('公司',companyContext)?.['公司名称']||'公司'):exportOn?'国外开发':pageOf(current)[1];if(current==='strategy'){strategyPage();return;}if(current==='companyDetail'){companyPage(companyContext);return;}$('#main').innerHTML=current==='home'?home():current==='later'?later():current==='storage'?storage():listing();showLatestTalks($('#main'));}

function strategyMarkdown(raw){
 const inline=t=>esc(t).replace(/\[([^\]]+)\]\((https:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
 let html='',inTable=false;
 for(const line of raw.split('\n')){
  if(line.startsWith('!['))continue;
  if(line.startsWith('|')){
   if(/^\|[\s:|\-]+\|$/.test(line))continue;
   if(!inTable){html+='<div class="strategy-table"><table>';inTable=true;}
   html+='<tr>'+line.split('|').slice(1,-1).map(c=>'<td>'+inline(c.trim())+'</td>').join('')+'</tr>';continue;
  }
  if(inTable){html+='</table></div>';inTable=false;}
  const heading=line.match(/^(#{1,4}) (.*)/);
  if(heading){const n=heading[1].length;html+=`<h${n}>${inline(heading[2])}</h${n}>`;}
  else if(line.trim())html+='<p>'+inline(line.replace(/^[-] /,'• ').replace(/^> /,''))+'</p>';
 }
 return html+(inTable?'</table></div>':'');
}
let strategyObserver=null;
async function strategyPage(){
 $('#main').innerHTML=header('战略日报','产品方向、政策变化与客户机会 · 每条信息保留来源')+'<p>正在读取本地日报…</p>';
 try{
  const {reports}=await api('/api/strategy');if(current!=='strategy')return;
  $('#main').innerHTML=header('战略日报','产品方向、政策变化与客户机会 · 每条信息保留来源')+`<section class="panel"><div class="panel-content"><label>选择日期 <select id="strategyDate">${reports.map(r=>`<option value="${esc(r.date)}">${esc(r.date)}</option>`).join('')}</select></label><div id="strategyReport"></div></div></section>`;
  if(!reports.length){$('#strategyReport').textContent='暂无日报。';return;}
  const show=async()=>{
   const date=$('#strategyDate').value;
   const r=await fetch('/strategy/'+date+'.html');if(!r.ok)throw Error('无法读取彩色日报');
   const layout=await r.text();if(current!=='strategy'||$('#strategyDate').value!==date)return;
   strategyObserver?.disconnect();
   $('#strategyReport').innerHTML=`<div class="strategy-actions"><a class="button" href="/strategy/${date}.md" download="${date}.md">下载 Markdown</a><a class="button" href="/strategy/${date}.png" target="_blank" rel="noopener">查看图版</a></div>`;
   const frame=document.createElement('iframe');frame.id='strategyLayout';frame.className='strategy-layout';frame.title=date+' 战略日报彩色排版';
   frame.setAttribute('sandbox','allow-same-origin allow-popups allow-popups-to-escape-sandbox');
   frame.onload=()=>{
    if(!frame.isConnected)return;
    const doc=frame.contentDocument,content=doc.querySelector('main');if(!content)return;
    const resize=()=>{if(frame.isConnected)frame.style.height=Math.ceil(content.getBoundingClientRect().height)+'px';};
    strategyObserver?.disconnect();strategyObserver=new ResizeObserver(resize);strategyObserver.observe(content);doc.fonts.ready.then(resize);resize();
   };
   frame.srcdoc=layout;$('#strategyReport').appendChild(frame);
  };
  $('#strategyDate').onchange=()=>show().catch(e=>toast(e.message));await show();
 }catch(e){if(current==='strategy')$('#main').innerHTML=header('战略日报','读取未完成')+`<p>${esc(e.message)}</p>`;}
}

function isLong(f){return /原话|整理稿|事实|判断|推测|问题|约定|条件|依据|反馈|动作|证据|什么|卡点|目标|来源|备注|问法|工艺|边界|标准|练习|为什么|原因|路径/.test(f)&&!f.includes('编号')&&!f.includes('日期依据')&&!f.includes('客户来源');}
function relationLabel(s,r){return [r._id,r['公司名称']||r['姓名']||r['终端产品']||r['完整型号']||r['下一步具体动作']||r['日期']||r['客户问题原话']].filter(Boolean).join(' · ');}
function openEditor(sheet,id=''){if(!state)return;const r=record(sheet,id)||{},fields=state.schema[sheet].filter((f,i)=>i>0&&!f.computed&&!f.readonly);editing={sheet,id,version:state.version,fields};dirty=false;$('#editKind').textContent=sheet;$('#editTitle').textContent=id?`编辑 ${id}`:`新增${sheet}`;$('#formError').textContent='';$('#formFields').innerHTML=fields.map((f,i)=>{let value=f.name==='延期原因'?'':r[f.name]??'';if(!id&&f.name==='公司编号'&&companyContext)value=companyContext;if(!id&&f.name==='项目编号'&&projectContext)value=projectContext;if(!id&&sheet==='测试轮次'&&f.name==='样品编号')value=sampleContext;if(['样品测试','测试轮次'].includes(sheet)&&f.name==='日期依据'&&!value)value='本人计划';if(!id&&sheet==='测试轮次'&&f.name==='状态')value='待安排';if(!id&&f.name==='负责人')value='我';if(!id&&f.name==='日期')value=localDay();if(!id&&sheet==='技术经验'&&f.name==='证据状态')value='待答复';const ident=`field${i}`;let control;if(f.relation)control=`<select id="${ident}" data-key="${esc(f.name)}" data-relation="${f.relation}"><option value="">暂不选择</option>${rows(f.relation).map(x=>`<option value="${esc(x._id)}" ${value===x._id?'selected':''}>${esc(relationLabel(f.relation,x))}</option>`).join('')}</select>`;else if(f.options.length)control=`<select id="${ident}" data-key="${esc(f.name)}"><option value="">待填写</option>${f.options.map(v=>`<option ${value===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`;else if(isLong(f.name))control=`<textarea id="${ident}" data-key="${esc(f.name)}" maxlength="30000">${esc(value)}</textarea>`;else control=`<input id="${ident}" data-key="${esc(f.name)}" type="${f.type==='number'?'number':f.type==='date'?'date':'text'}" ${f.type==='number'?'min="0" step="any"':''} value="${esc(value)}">`;return `<label class="field ${isLong(f.name)?'wide':''}">${esc(sheet==='样品测试'?({'完整型号':'对内型号','签收日期':'收样日期','收件联系人编号':'收样人'}[f.name]||friendly[f.name]||f.name):(friendly[f.name]||f.name))}${control}</label>`;}).join('');if(['样品测试','测试轮次'].includes(sheet))$('#formFields').insertAdjacentHTML('afterbegin','<p class="visit-note">保存会同步关联跟进待办与项目推进记录。已寄出、已签收、测试中或待复测须填写回访/反馈日期；客户未承诺时可填写本人计划。改期需填写延期原因。</p>');if(sheet==='样品测试'){arrangeSampleFields();const plan=$('#formFields [data-key="计划测试日期"]');if(plan){plan.closest('label').insertAdjacentHTML('beforeend','<button type="button" class="text-btn" data-recalc-test>按到货日期重算</button><small class="test-date-hint"></small>');applyTestDate($('#formFields'));}}$('#editor').showModal();filterRelations();}
function arrangeSampleFields(){const box=$('#formFields'),primary=['申请时间','物料名称','完整型号','单位','数量','收件联系人编号','快递单号','状态'],extra=['图号','规格','业务员','备注','签收日期','计划测试日期','寄出日期','约定反馈日期','日期依据','问题与下一步','延期原因'];const section=document.createElement('section');section.className='field wide sample-edit-section';section.innerHTML='<div class="form-grid sample-primary"></div><div class="form-grid sample-ship" hidden></div>';for(const key of primary){const el=box.querySelector(`[data-key="${key}"]`);if(el)section.querySelector('.sample-primary').append(el.closest('label'));}box.append(section);const more=document.createElement('details');more.className='field wide visit-more sample-more';more.innerHTML='<summary>需要时再填</summary><div class="form-grid"></div>';for(const key of extra){const el=box.querySelector(`[data-key="${key}"]`);if(el)more.querySelector('.form-grid').append(el.closest('label'));}box.append(more);const rest=document.createElement('details');rest.className='field wide visit-more';rest.innerHTML='<summary>测试条件与来源补充</summary><div class="form-grid"></div>';for(const label of [...box.children].filter(x=>x.matches('label.field')))rest.querySelector('div').append(label);if(rest.querySelector('label'))box.append(rest);placeSampleExtra(box,'[data-key="状态"]',['[data-key="寄出日期"]','[data-key="约定反馈日期"]','[data-key="日期依据"]']);}
function filterRelations(){const controls=[...$('#formFields').querySelectorAll('[data-key]')],get=k=>controls.find(c=>c.dataset.key===k)?.value;const pid=get('项目编号'),cid=get('公司编号')||record('用胶项目',pid)?.['公司编号'];for(const el of controls.filter(c=>c.dataset.relation&&c.dataset.relation!=='公司')){for(const opt of el.options){if(!opt.value)continue;const r=record(el.dataset.relation,opt.value);opt.hidden=!!((cid&&companyId(el.dataset.relation,r)&&companyId(el.dataset.relation,r)!==cid)||(pid&&el.dataset.relation==='样品测试'&&r?.['项目编号']!==pid));}if(el.selectedOptions[0]?.hidden)el.value='';}}

function closeEditor(){if(saving)return;if(dirty&&!confirm('尚未保存，放弃这次填写？'))return;$('#editor').close();editing=null;dirty=false;}
async function postRecord(sheet,values,id=''){const res=await api('/api/records',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Token':$('meta[name="workspace-token"]').content},body:JSON.stringify({sheet,id,version:state.version,values})});state.version=res.version;return res;}
let transcriptTarget='',transcriptPayload=null;
function openTranscript(id){const r=record('沟通记录',id);if(!r)return;transcriptTarget=id;transcriptPayload=null;$('#transcriptTitle').textContent=`上传校对稿 · ${companyName('沟通记录',r)} · ${r['日期']}`;$('#transcriptFile').value='';$('#transcriptPreview').textContent='选择文件后先检查，再保存。';$('#transcriptError').textContent='';$('#saveTranscript').disabled=true;$('#transcriptUpload').showModal();}
function closeTranscript(){if(saving)return;$('#transcriptUpload').close();transcriptTarget='';transcriptPayload=null;}
async function fileBase64(file){const bytes=new Uint8Array(await file.arrayBuffer()),chunks=[];for(let i=0;i<bytes.length;i+=32768)chunks.push(String.fromCharCode(...bytes.subarray(i,i+32768)));return btoa(chunks.join(''));}
async function previewTranscript(){const file=$('#transcriptFile').files?.[0];transcriptPayload=null;$('#saveTranscript').disabled=true;$('#transcriptError').textContent='';if(!file)return;if(!file.name.toLowerCase().endsWith('.docx')||file.size>1500000){$('#transcriptError').textContent='请选择小于 1.5 MB 的 .docx 文件。';return;}$('#transcriptPreview').textContent='正在检查段落和说话人…';try{const payload={id:transcriptTarget,version:state.version,filename:file.name,content:await fileBase64(file)};const preview=await api('/api/transcript/preview',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Token':$('meta[name="workspace-token"]').content},body:JSON.stringify(payload)});transcriptPayload=payload;$('#transcriptPreview').innerHTML=`<strong>可导入：${esc(preview.count)} 段对话</strong><p>${esc(preview.filename)} · ${esc(preview.date)}</p><p>前 3 段：${preview.sample.map(t=>`${esc(t.speaker)} ${esc(t.time)}：${esc(t.text)}`).join('<br>')}</p><small>确认后更新这条记录的整理稿，并在本机保存校对文件。</small>`;$('#saveTranscript').disabled=false;}catch(err){$('#transcriptPreview').textContent='检查未通过。';$('#transcriptError').textContent=err.message;}}
async function saveTranscript(){if(saving||!transcriptPayload)return;saving=true;$('#saveTranscript').disabled=true;$('#transcriptError').textContent='';try{await api('/api/transcript/save',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Token':$('meta[name="workspace-token"]').content},body:JSON.stringify(transcriptPayload)});$('#transcriptUpload').close();transcriptTarget='';transcriptPayload=null;await load();toast('校对稿已导入，原始转写已保留。');}catch(err){$('#transcriptError').textContent=err.message;}finally{saving=false;if(transcriptPayload)$('#saveTranscript').disabled=false;}}
let pendingDelete=null;
function projectDeleteSummary(id){const samples=rows('样品测试').filter(r=>r['项目编号']===id),ids=new Set(samples.map(r=>r._id));const trials=rows('测试轮次').filter(r=>r['项目编号']===id||ids.has(r['样品编号'])),tasks=rows('跟进待办').filter(r=>r['项目编号']===id||ids.has(r['样品编号']));return `同时删除：${samples.length} 条样品、${trials.length} 轮测试、${tasks.length} 条跟进待办。`;}
function openDeleteRecord(sheet,id){const r=record(sheet,id);if(!r)return;pendingDelete={sheet,id};$('#confirmDeleteKind').textContent=sheet==='用胶项目'?'项目':sheet==='跟进待办'?'跟进':'样品';$('#confirmDeleteError').textContent='';const lines=sheet==='用胶项目'?['删除这个项目？','公司：'+companyName(sheet,r),'项目：'+(r['终端产品']||r['用胶部位']||id),projectDeleteSummary(id),'公司、联系人、拜访原文和经验保留，解除相关项目/任务关联。','删除前自动保存完整Excel备份，可从备份恢复。']:sheet==='跟进待办'?['删除这条跟进？将从本地表去掉。','公司：'+(companyName(sheet,r)||'未关联公司'),'事项：'+(r['下一步具体动作']||id)]:['删除这款样品？将从本地表去掉。','公司：'+(companyName(sheet,r)||'未关联公司'),'型号：'+(r['完整型号']||'型号未填')];if(sheet==='跟进待办'&&r['事项类型'])lines.push('类型：'+r['事项类型']);if(sheet==='样品测试'&&r['物料名称'])lines.push('物料：'+r['物料名称']);$('#confirmDeleteText').textContent=lines.join('\n');if(!$('#confirmDelete').open)$('#confirmDelete').showModal();}
function closeDeleteSample(){if(saving)return;pendingDelete=null;if($('#confirmDelete').open)$('#confirmDelete').close();}
async function deleteRecord(){const item=pendingDelete;if(saving||!item)return;saving=true;$('#doConfirmDelete').disabled=true;$('#confirmDeleteError').textContent='';try{const res=await api('/api/delete',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Token':$('meta[name="workspace-token"]').content},body:JSON.stringify({sheet:item.sheet,id:item.id,version:state.version})});state.version=res.version;if($('#detail').open)$('#detail').close();if(projectContext===item.id)projectContext='';pendingDelete=null;if($('#confirmDelete').open)$('#confirmDelete').close();await load();toast('已删除 '+item.id+'。');}catch(err){$('#confirmDeleteError').textContent=err.message;}finally{saving=false;if($('#doConfirmDelete'))$('#doConfirmDelete').disabled=false;}}
async function postBatch(records){const res=await api('/api/batch',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Token':$('meta[name="workspace-token"]').content},body:JSON.stringify({version:state.version,records})});state.version=res.version;return res;}
async function save(e){e.preventDefault();if(saving||!editing)return;const values={};for(const el of $('#formFields').querySelectorAll('[data-key]'))values[el.dataset.key]=el.value;const form=editing;saving=true;$('#saveButton').disabled=true;$('#formError').textContent='';try{await postRecord(form.sheet,values,form.id);dirty=false;editing=null;$('#editor').close();await load();toast(['样品测试','测试轮次'].includes(form.sheet)?'已保存，同步跟进待办与项目推进记录。':'已写入本地 Excel。');}catch(err){$('#formError').textContent=err.message;}finally{saving=false;$('#saveButton').disabled=false;}}
function placeSampleExtra(root,statusSelector,keys){if(!root)return;const ship=root.querySelector(':scope > .sample-ship, .sample-edit-section > .sample-ship');const more=root.querySelector('.sample-more .form-grid');if(!ship||!more)return;const need=['已寄出','已签收','测试中'].includes(root.querySelector(statusSelector)?.value||'');for(const key of keys){const el=root.querySelector(key);const label=el?.closest('label');if(label)(need?ship:more).append(label);}ship.hidden=!need;}
function sampleLine(units,people){const unitOptions=units.map(v=>`<option>${esc(v)}</option>`).join(''),peopleOptions=people.map(p=>`<option value="${esc(p._id)}">${esc(p['姓名'])}</option>`).join('');return `<div class="sample-line sample-application"><label>申请时间<input data-k="applied" type="date"></label><label>物料名称<input data-k="material" placeholder="如：黄胶"></label><label>对内型号<input data-k="model" placeholder="未知可留空"></label><label>数量<input data-k="qty" type="number" min="0" step="any" placeholder="未知可留空"></label><label>单位<select data-k="unit"><option value="">请选择单位</option>${unitOptions}</select></label><label>收样人<select data-k="person"><option value="">请选择客户联系人</option>${peopleOptions}</select></label><label>快递单号<input data-k="track" placeholder="未寄出可留空"></label><label>当前状态<select data-k="status"><option>已申请</option><option>待寄出</option><option>已寄出</option><option>已签收</option><option>测试中</option></select></label><div class="sample-ship" hidden></div><details class="sample-more visit-more"><summary>需要时再填</summary><div class="form-grid"><label>图号<input data-k="drawing" placeholder="按图纸编号填写"></label><label>规格<input data-k="spec" placeholder="如：100 mL/支"></label><label>业务员<input data-k="salesperson" placeholder="实际经办人"></label><label class="sample-wide">备注<textarea data-k="note" placeholder="申请说明或待核事项"></textarea></label><label>收样日期<input type="date" data-k="received"></label><label>计划测试日期<input type="date" data-k="planned"><button type="button" class="text-btn" data-recalc-test>按到货日期重算</button><small class="test-date-hint">到货后的第3个中国法定工作日；到货当天不计，可修改。</small></label><label>寄出日期<input type="date" data-k="sent"></label><label>回访 / 测试反馈日期<input type="date" data-k="due"></label><label>日期依据<select data-k="basis"><option>本人计划</option><option>客户约定</option></select></label></div></details></div>`;}

function fillSamplePeople(){const cid=$('#sampleCompany')?.value||'';document.querySelectorAll('#sampleLines [data-k="person"]').forEach(sel=>{const keep=sel.value;sel.innerHTML='<option value="">请选择客户联系人</option>'+peopleOf(cid).map(p=>`<option value="${esc(p._id)}">${esc(p['姓名'])}</option>`).join('');if([...sel.options].some(o=>o.value===keep))sel.value=keep;});}
function addSampleLine(){const units=state.schema['样品测试'].find(f=>f.name==='单位').options;$('#sampleLines').insertAdjacentHTML('beforeend',sampleLine(units,peopleOf($('#sampleCompany').value)));placeSampleExtra($('#sampleLines').lastElementChild,'[data-k="status"]',['[data-k="sent"]','[data-k="due"]','[data-k="basis"]']);}
function openSamples(preferred){if(!state)return;sampleDirty=false;$('#sampleError').textContent='';const units=state.schema['样品测试'].find(f=>f.name==='单位').options;const cid=preferred||companyContext||'';$('#sampleFields').innerHTML=`<label class="field wide">供应商 / 客户名称（关联公司）<select id="sampleCompany"><option value="">请选择公司</option>${rows('公司').map(c=>`<option value="${esc(c._id)}" ${c._id===cid?'selected':''}>${esc(c['公司名称'])}</option>`).join('')}</select></label><label class="field wide">用胶项目<select id="sampleProject"></select></label><div class="sample-lines"><div id="sampleLines">${sampleLine(units,peopleOf(cid))}</div><button type="button" class="button" id="addSampleLine">＋ 再加一条</button><p class="visit-note">每条一款。型号、数量不知道可以先空着。选了已寄出、已签收或测试中，再补寄出日期和回访日期。</p></div>`;$('#sampleForm').querySelector('#addSampleLine').onclick=()=>{sampleDirty=true;addSampleLine();};fillProjectSelect('sampleProject', $('#sampleCompany').value, projectContext);fillSamplePeople();document.querySelectorAll('#sampleLines .sample-line').forEach(line=>placeSampleExtra(line,'[data-k="status"]',['[data-k="sent"]','[data-k="due"]','[data-k="basis"]']));$('#samples').showModal();}
let sampleDirty=false;
async function saveSamples(e){e.preventDefault();if(saving)return;const company=$('#sampleCompany').value;const lines=[...document.querySelectorAll('#sampleLines .sample-line')].map(row=>({model:row.querySelector('[data-k="model"]').value.trim(),qty:row.querySelector('[data-k="qty"]').value.trim(),unit:row.querySelector('[data-k="unit"]').value,person:row.querySelector('[data-k="person"]').value,track:row.querySelector('[data-k="track"]').value.trim(),applied:row.querySelector('[data-k="applied"]').value,drawing:row.querySelector('[data-k="drawing"]').value.trim(),material:row.querySelector('[data-k="material"]').value.trim(),spec:row.querySelector('[data-k="spec"]').value.trim(),salesperson:row.querySelector('[data-k="salesperson"]').value.trim(),note:row.querySelector('[data-k="note"]').value.trim(),received:row.querySelector('[data-k="received"]').value,planned:row.querySelector('[data-k="planned"]').value,status:row.querySelector('[data-k="status"]').value,sent:row.querySelector('[data-k="sent"]').value,due:row.querySelector('[data-k="due"]').value,basis:row.querySelector('[data-k="basis"]').value})).filter(x=>x.model||x.material||x.qty||x.track||x.applied||x.drawing||x.spec||x.salesperson||x.note||x.received||x.sent||x.due||x.person);$('#sampleError').textContent='';if(!company){$('#sampleError').textContent='请选择公司。';return;}if(!lines.length){$('#sampleError').textContent='请至少填写一条样品申请信息。';return;}if(lines.some(x=>!x.model&&!x.material)){$('#sampleError').textContent='每一条至少填写物料名称或对内型号。';return;}saving=true;$('#sampleSave').disabled=true;try{const project=record('用胶项目',$('#sampleProject').value);if(!project||project['公司编号']!==company)throw Error('请先选择用胶项目；如没有，请在项目推进中新增。');const records=[];for(const line of lines){const values={项目编号:project._id,完整型号:line.model,申请时间:line.applied,图号:line.drawing,物料名称:line.material,规格:line.spec,业务员:line.salesperson,备注:line.note,签收日期:line.received,计划测试日期:line.planned,状态:line.status,收件联系人编号:line.person,快递单号:line.track,寄出日期:line.sent,约定反馈日期:line.due,日期依据:line.basis};if(line.qty){values['数量']=line.qty;values['单位']=line.unit;}records.push({sheet:'样品测试',values});}await postBatch(records);sampleDirty=false;$('#samples').close();await load();toast('已保存 '+records.length+' 条样品，并同步关联跟进。');}catch(err){$('#sampleError').textContent=err.message;}finally{saving=false;$('#sampleSave').disabled=false;}}
function closeSamples(){if(saving)return;if(sampleDirty&&!confirm('这些样品还没写入，放弃？'))return;$('#samples').close();sampleDirty=false;}
function openVisit(){if(!state)return;const channels=state.schema['沟通记录'].find(f=>f.name==='渠道').options,roles=state.schema['沟通记录'].find(f=>f.name==='我的角色').options,units=state.schema['样品测试'].find(f=>f.name==='单位').options;visitDirty=false;$('#visitError').textContent='';$('#visitFields').innerHTML=`<label class="field">公司<select id="visitCompany"><option value="">请选择公司</option>${rows('公司').map(c=>`<option value="${esc(c._id)}" ${c._id===companyContext?'selected':''}>${esc(c['公司名称'])}</option>`).join('')}</select></label><label class="field">用胶项目<select id="visitProject"></select></label><label class="field">联系人<select id="visitPerson"></select></label><label class="field">日期<input id="visitDate" type="date" value="${localDay()}"></label><label class="field">渠道<select id="visitChannel">${channels.map(v=>`<option ${v==='面访'?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="field">聊天工具<select id="visitTool"><option value="">不标</option><option>WhatsApp</option><option>微信</option><option>邮件</option></select></label><label class="field">我的角色<select id="visitRole">${roles.map(v=>`<option ${v==='主谈'?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="field wide">客户说了什么<textarea id="visitCustomer" maxlength="30000" placeholder="只贴客户原话。整段转写还没拆开就留空，路径写在下面。"></textarea></label><label class="field wide">我说了什么<textarea id="visitMine" maxlength="30000" placeholder="只贴我方原话。"></textarea></label><label class="field wide">这次做成了什么<textarea id="visitFact" maxlength="30000" placeholder="只写双方确认的事实。"></textarea></label><label class="field wide">当时判断<textarea id="visitJudge" maxlength="30000" placeholder="你当时怎么判断。这不是客户事实。"></textarea></label><label class="field wide">本轮只推进的一件事<textarea id="visitGoal" maxlength="30000"></textarea></label><label class="field wide">哪里可以改<textarea id="visitImprove" maxlength="30000"></textarea></label><label class="field wide">转写文件路径<textarea id="visitPath" maxlength="30000" placeholder="录音转文字文件的位置"></textarea></label><p class="visit-note">下一步另记一条跟进。样品还没建用胶项目时，型号和数量先写在跟进里；申请或寄出后再登记样品。</p><label class="field">下一步<select id="visitKind"><option value="">先不安排</option><option>送样</option><option>确认签收</option><option>测试反馈</option><option>补资料</option><option>技术答疑</option><option>定期回访</option><option>拜访</option><option>邮件跟进</option><option>社媒跟进</option></select></label><label class="field">计划日期<input id="visitDue" type="date"></label><label class="field wide">下一步怎么做<input id="visitAction" placeholder="例如：向同事确认用哪支胶，并写下原因"></label><label class="field">样品型号<input id="visitModel" placeholder="未知留空"></label><label class="field">数量<input id="visitQty" type="number" min="0" step="any" placeholder="未知留空"></label><label class="field">单位<select id="visitUnit"><option value="">待定</option>${units.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`;const more=document.createElement('details');more.className='field wide visit-more';more.innerHTML='<summary>判断、改进与转写来源（展开填写）</summary><div class="form-grid"></div>';for(const id of ['visitJudge','visitImprove','visitPath','visitModel','visitQty','visitUnit'])more.querySelector('div').appendChild($('#'+id).closest('label'));$('#visitFields').appendChild(more);fillVisitPeople();fillProjectSelect('visitProject',$('#visitCompany').value,projectContext);$('#visit').showModal();}
function fillProjectSelect(id,cid,selected=''){const el=$('#'+id);if(!el)return;el.innerHTML='<option value="">请选择项目（尚未明确可留空）</option>'+rows('用胶项目').filter(p=>p['公司编号']===cid).map(p=>`<option value="${esc(p._id)}" ${p._id===selected?'selected':''}>${esc(p['终端产品']||p['用胶部位']||'用胶点待明确')} · ${esc(p._id)}</option>`).join('');}
function fillVisitPeople(){const sel=$('#visitPerson');if(!sel)return;const keep=sel.value,cid=$('#visitCompany').value;sel.innerHTML='<option value="">先不指定</option>'+peopleOf(cid).map(p=>`<option value="${esc(p._id)}">${esc(p['姓名'])}</option>`).join('');if([...sel.options].some(o=>o.value===keep))sel.value=keep;}
function closeVisit(){if(saving)return;if(visitDirty&&!confirm('这次拜访还没写入，放弃？'))return;$('#visit').close();visitDirty=false;}
async function saveVisit(e){e.preventDefault();if(saving)return;const company=$('#visitCompany').value,customer=$('#visitCustomer').value.trim(),mine=$('#visitMine').value.trim(),fact=$('#visitFact').value.trim(),judge=$('#visitJudge').value.trim(),goal=$('#visitGoal').value.trim(),improve=$('#visitImprove').value.trim(),path=$('#visitPath').value.trim();const tool=$('#visitTool').value;let channel=$('#visitChannel').value,shownFact=fact;if(tool==='WhatsApp'){channel='社交媒体';if(!shownFact.startsWith('这是 WhatsApp。'))shownFact=shownFact?'这是 WhatsApp。\n'+shownFact:'这是 WhatsApp。';}else if(tool==='微信')channel='微信';else if(tool==='邮件')channel='邮件';$('#visitError').textContent='';if(!company||!$('#visitDate').value){$('#visitError').textContent='请选择公司并填写日期。';return;}if(!customer&&!mine&&!fact&&!path){$('#visitError').textContent='请写下原话、做成了什么，或转写文件路径。';return;}const kind=$('#visitKind').value,action=$('#visitAction').value.trim(),model=$('#visitModel').value.trim(),qty=$('#visitQty').value.trim(),unit=$('#visitUnit').value;if(kind&&!action&&!(kind==='送样'&&(model||qty))){$('#visitError').textContent='请写下一步怎么做。';return;}saving=true;$('#visitSave').disabled=true;try{const records=[{sheet:'沟通记录',key:'talk',values:{日期:$('#visitDate').value,公司编号:company,项目编号:$('#visitProject').value,联系人编号:$('#visitPerson').value,渠道:channel,我的角色:$('#visitRole').value,客户原话及时间戳:customer,我方原话及时间戳:mine,已确认事实:shownFact,AI判断或推测:judge,本次约定:goal,待核实问题:improve,原始转写路径或链接:path}}];if(kind){const bits=[];if(action)bits.push(action);if(kind==='送样'&&model)bits.push('型号 '+model);if(kind==='送样'&&qty)bits.push('数量 '+qty+(unit?unit:''));records.push({sheet:'跟进待办',values:{公司编号:company,项目编号:$('#visitProject').value,联系人编号:$('#visitPerson').value,事项类型:kind,下一步具体动作:bits.join('，'),负责人:'我',计划日期:$('#visitDue').value,日期依据:$('#visitDue').value?'本人计划':'',状态:'待办',来源沟通编号:'@record:talk'}});}await postBatch(records);visitDirty=false;$('#visit').close();await load();toast(kind?'拜访和跟进已写入。':'拜访已写入。');}catch(err){$('#visitError').textContent=err.message;}finally{saving=false;$('#visitSave').disabled=false;}}
function experienceDialogue(text){const turns=[];let active=null;for(const line of String(text||'').split(/\r?\n/)){const clean=line.replace(/^\[段落\d+\]\s*/,'');const match=clean.match(/^(我自己|答复人)\s+(\d{1,2}:\d{2}(?::\d{2})?)\s*$/);if(match){active={name:match[1],time:match[2],lines:[]};turns.push(active);}else if(active&&clean.trim())active.lines.push(clean);}return turns.filter(t=>t.lines.length);}
function experienceThread(r){const turns=experienceDialogue(r['答复原文']);if(!turns.length)return '';return `<section class="detail-field wide experience-dialogue"><div class="panel-head"><h2>请教对话</h2><small>我自己在左 · 答复人在右</small></div><div class="thread">${turns.map(t=>`<div class="bubble ${t.name==='我自己'?'left question-bubble':'right answer-bubble'}"><span class="who">${esc(t.name)} · ${esc(t.time)}</span><p>${esc(t.lines.join('\n'))}</p></div>`).join('')}</div><details class="project-more"><summary>查看完整原文与段落定位</summary><div class="fact-value">${esc(r['答复原文'])}</div></details></section>`;}
function detail(sheet,id){const r=record(sheet,id);if(!r)return;if(sheet==='公司'){companyPage(id);if($('#detail').open)$('#detail').close();return;}$('#detailTitle').textContent=`${sheet} · ${id}`;let extra='';if(sheet==='技术经验')extra=experienceThread(r);if(sheet==='样品测试')extra=`<div class="detail-field wide">${trialHistory(id)}</div>`;if(sheet==='联系人'){const cid=r['公司编号'];extra=`<div class="detail-field wide"><div class="fact-label">同一公司的其他人</div>${peopleOf(cid).filter(p=>p._id!==id).map(personButton).join('')||'<p class="muted">没有其他联系人。</p>'}</div>`;}if(sheet==='沟通记录')extra=`<div class="detail-field wide">${threadFrame(companyTalks(r['公司编号']))}</div>`;$('#detailBody').innerHTML=(['沟通记录','样品测试','技术经验'].includes(sheet)?extra:'')+Object.entries(r).filter(([k,v])=>!k.startsWith('_')&&!String(k).includes('〔自动〕')&&!(sheet==='样品测试'&&(v===''||v==null))&&!(sheet==='技术经验'&&extra&&k==='答复原文')&&!(sheet==='沟通记录'&&(['客户原话及时间戳','我方原话及时间戳','客户整理稿及时间戳','我方整理稿及时间戳'].includes(k)))).map(([k,v])=>{const target=REL(sheet,k);return `<div class="detail-field ${isLong(k)?'wide':''}"><div class="fact-label">${esc(friendly[k]||k)}</div><div class="fact-value">${target&&v?`<button class="text-btn" data-detail="${target}" data-id="${esc(v)}">${esc(relationLabel(target,record(target,v)||{_id:v}))}</button>`:esc(v)||'未记录'}</div></div>`;}).join('')+(['沟通记录','样品测试','技术经验'].includes(sheet)?'':extra)+`<div class="detail-field wide"><button class="button primary" data-edit="${sheet}" data-id="${esc(id)}">编辑</button>${sheet==='沟通记录'&&r['客户原话及时间戳']?.includes('[段落')?` <button class="button" data-upload="${esc(id)}">上传校对稿</button>`:''}${sheet==='用胶项目'?` <button class="button danger" data-action="delete-record" data-sheet="用胶项目" data-id="${esc(id)}">删除项目</button>`:''}${companyId(sheet,r)?` <button class="button" data-company="${esc(companyId(sheet,r))}">回到这家公司</button>`:''}</div>`;const actions=$('#detailBody').lastElementChild;$('#detailActions').replaceChildren();if(actions){actions.className='detail-action-buttons';$('#detailActions').append(actions);}if(!$('#detail').open)$('#detail').showModal();showLatestTalks($('#detail'));}
function REL(sheet,f){return state.schema[sheet].find(x=>x.name===f)?.relation;}
document.addEventListener('click',e=>{if(e.target.closest('[data-recalc-test]')){e.preventDefault();const row=e.target.closest('.sample-line');applyTestDate(row||$('#formFields'),!!row,true);if(row)sampleDirty=true;else dirty=true;return;}const b=e.target.closest('[data-save-project],[data-open-project],[data-trial],[data-view],[data-add],[data-edit],[data-detail],[data-company],[data-action],[data-type],[data-market],[data-when],[data-who],[data-upload]');if(!b)return;if(b.dataset.saveProject){e.preventDefault();saveBusiness(b.dataset.saveProject);return;}if(b.dataset.openProject){e.preventDefault();$('#detail').close();if(current==='用胶项目'&&projectContext===b.dataset.openProject){projectContext='';render();return;}projectContext=b.dataset.openProject;companyContext=record('用胶项目',projectContext)?.['公司编号']||'';current='用胶项目';sourceFilter='';query='';statusFilter='';render();document.getElementById('project-'+projectContext)?.scrollIntoView({block:'start'});return;}if(b.dataset.upload){e.preventDefault();openTranscript(b.dataset.upload);return;}if(b.dataset.trial){e.preventDefault();sampleContext=b.dataset.trial;projectContext=record('样品测试',sampleContext)?.['项目编号']||'';companyContext=record('用胶项目',projectContext)?.['公司编号']||'';$('#detail').close();openEditor('测试轮次');return;}if(b.dataset.project){projectContext=b.dataset.project;companyContext=record('用胶项目',projectContext)?.['公司编号']||'';}if(b.closest('.brand')&&b.dataset.view){e.preventDefault();go('home');return;}if(b.dataset.view){e.preventDefault();go(b.dataset.view);return;}if(b.dataset.add){e.preventDefault();openEditor(b.dataset.add);return;}if(b.dataset.edit){e.preventDefault();$('#detail').close();openEditor(b.dataset.edit,b.dataset.id);return;}if(b.dataset.detail){e.preventDefault();if(b.dataset.detail==='company'){companyPage(b.dataset.id);return;}detail(b.dataset.detail,b.dataset.id);return;}if(b.dataset.company){e.preventDefault();$('#detail').close();companyPage(b.dataset.company);return;}if(b.dataset.action==='toggle-zh'){e.preventDefault();const frame=b.closest('.thread-frame');if(!frame)return;const on=frame.classList.toggle('show-zh');b.textContent=on?'原文':'语句通顺的中文';frame.querySelectorAll('.bubble p').forEach(p=>{const next=on?p.dataset.fluent:p.dataset.original;if(next)p.textContent=next;});return;}if(b.dataset.action==='clear-context'){e.preventDefault();companyContext='';sourceFilter='';render();return;}if(b.dataset.action==='visit'){e.preventDefault();openVisit();return;}if(b.dataset.action==='samples'){e.preventDefault();openSamples(b.dataset.sampleCompany||'');return;}if(b.dataset.action==='delete-record'){e.preventDefault();openDeleteRecord(b.dataset.sheet,b.dataset.id);return;}if(b.dataset.when!==undefined){e.preventDefault();actionWhen=b.dataset.when;render();return;}if(b.dataset.who!==undefined){e.preventDefault();actionWho=b.dataset.who;render();return;}if(b.dataset.type!==undefined&&dataSheet()==='跟进待办'){e.preventDefault();typeFilter=b.dataset.type;render();return;}if(b.dataset.market!==undefined&&dataSheet()==='公司'){e.preventDefault();marketFilter=b.dataset.market;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;if(current==='home'){const list=homeTasks();const body=$('#actionBody');if(body)body.innerHTML=list.length?todayLines(list):(actionWhen==='today'&&!actionWho?'<p class="muted">今天没有要做的事。</p>':'<p class="muted">这里没有。</p>');return;}const painted=paintList(filtered());$('#listBody').innerHTML=painted.body;showLatestTalks($('#listBody'));const n=$('.toolbar .count');if(n)n.textContent=painted.count;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-k="status"]'))placeSampleExtra(e.target.closest('.sample-line'),'[data-k="status"]',['[data-k="sent"]','[data-k="due"]','[data-k="basis"]']);if(e.target.matches('[data-key="状态"]')&&e.target.closest('#formFields'))placeSampleExtra($('#formFields'),'[data-key="状态"]',['[data-key="寄出日期"]','[data-key="约定反馈日期"]','[data-key="日期依据"]']);if(e.target.matches('[data-k="received"]'))applyTestDate(e.target.closest('.sample-line'),true);if(editing?.sheet==='样品测试'&&e.target.matches('[data-key="签收日期"]'))applyTestDate($('#formFields'));if(e.target.id==='statusFilter'){statusFilter=e.target.value;render();}if(e.target.id==='visitCompany'){visitDirty=true;fillVisitPeople();fillProjectSelect('visitProject',$('#visitCompany').value,'');}if(e.target.id==='visitTool'){const map={WhatsApp:'社交媒体',微信:'微信',邮件:'邮件'};if(map[e.target.value])$('#visitChannel').value=map[e.target.value];}if(e.target.id==='sampleCompany'){sampleDirty=true;fillSamplePeople();fillProjectSelect('sampleProject',$('#sampleCompany').value,'');}});
